<?php require_once 'partials.php';allow(['admin','gestao','cliente']);
if($_SERVER['REQUEST_METHOD']==='POST' && in_array(role(),['admin','gestao'])){
 if(($_POST['action']??'')==='new'){
  $_SESSION['payments'][]=['id'=>next_id('payments'),'client_id'=>(int)$_POST['client_id'],'desc'=>trim($_POST['desc']),'due'=>$_POST['due'],'value'=>(float)str_replace(',','.',str_replace('.','',$_POST['value'])),'status'=>'Em aberto'];
 } elseif(($_POST['action']??'')==='paid'){
  foreach($_SESSION['payments'] as &$p)if($p['id']==(int)$_POST['id']){$p['status']='Pago';break;}unset($p);
 }
 header('Location:financeiro.php');exit;
}
header_page('Financeiro','fin');
$payments=$_SESSION['payments']; if(role()==='cliente')$payments=array_values(array_filter($payments,fn($x)=>$x['client_id']==$_SESSION['user']['client_id']));
$totalOpen=0;$overdue=0;$lateClients=[];
foreach($payments as $p){if($p['status']!=='Pago'){$totalOpen+=$p['value'];if(payment_state($p)==='Vencido'){$overdue+=$p['value'];$lateClients[$p['client_id']]=1;}}}
?>
<header class="pagehead"><div><span class="kicker">FINANCEIRO</span><h1><?=role()==='cliente'?'Meu financeiro':'Contas a receber'?></h1><p><?=role()==='cliente'?'Acompanhe seus honorários, vencimentos e pagamentos.':'Acompanhe recebíveis, vencimentos e clientes com pendências.'?></p></div><?php if(role()!=='cliente'):?><button class="primary" onclick="payModal.showModal()">+ Nova cobrança</button><?php endif;?></header>
<div class="metrics financial"><div class="metric"><small>TOTAL A RECEBER</small><strong>R$ <?=money_br($totalOpen)?></strong><span>parcelas em aberto</span></div><div class="metric danger"><small>VALOR VENCIDO</small><strong>R$ <?=money_br($overdue)?></strong><span>requer atenção</span></div><?php if(role()!=='cliente'):?><div class="metric"><small>CLIENTES INADIMPLENTES</small><strong><?=count($lateClients)?></strong><span>com parcelas vencidas</span></div><?php endif;?><div class="metric"><small>PARCELAS</small><strong><?=count($payments)?></strong><span>neste ambiente</span></div></div>
<?php if(role()!=='cliente'):?><section class="card"><div class="sectionhead"><div><span class="kicker">PRIORIDADES</span><h2>Clientes com pagamento em aberto</h2></div></div><div class="table"><div class="tr financehead"><span>Cliente</span><span>Cobrança</span><span>Vencimento</span><span>Valor</span><span>Status</span><span></span></div>
<?php foreach($payments as $p): if($p['status']==='Pago')continue;$c=find_client($p['client_id']);$st=payment_state($p);?><div class="tr financerow searchable"><span><b><?=e($c['name']??'Cliente')?></b><small><?=e($c['doc']??'')?></small></span><span><?=e($p['desc'])?></span><span><?=date('d/m/Y',strtotime($p['due']))?><?php if($st==='Vencido'):?><small><?=days_late($p)?> dias em atraso</small><?php endif;?></span><span><b>R$ <?=money_br($p['value'])?></b></span><span><i class="status <?=strtolower(str_replace(' ','-',$st))?>"><?=e($st)?></i></span><span><form method="post"><input type="hidden" name="action" value="paid"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="ghost">Marcar pago</button></form></span></div><?php endforeach;?></div></section><?php endif;?>
<section class="card"><div class="sectionhead"><div><span class="kicker">EXTRATO</span><h2><?=role()==='cliente'?'Minhas parcelas':'Todas as cobranças'?></h2></div></div><div class="table"><div class="tr th"><span>Descrição</span><span>Vencimento</span><span>Valor</span><span>Status</span></div><?php foreach($payments as $p):$st=payment_state($p);?><div class="tr"><span><b><?=e($p['desc'])?></b><?php if(role()!=='cliente'):$c=find_client($p['client_id']);?><small><?=e($c['name']??'')?></small><?php endif;?></span><span><?=date('d/m/Y',strtotime($p['due']))?></span><span>R$ <?=money_br($p['value'])?></span><span><i class="status <?=strtolower(str_replace(' ','-',$st))?>"><?=e($st)?></i></span></div><?php endforeach;?></div></section>
<?php if(role()!=='cliente'):?><dialog id="payModal"><form method="post" class="modal"><input type="hidden" name="action" value="new"><div class="sectionhead"><h2>Nova cobrança</h2><button type="button" class="x" onclick="payModal.close()">×</button></div><label>Cliente<select name="client_id"><?php foreach($_SESSION['clients'] as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Descrição<input name="desc" placeholder="Ex.: Honorários — Parcela 1/4" required></label><div class="grid2"><label>Vencimento<input type="date" name="due" required></label><label>Valor<input name="value" placeholder="750,00" required></label></div><button class="primary">Cadastrar cobrança</button></form></dialog><?php endif;?>
